import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.resolve(__dirname, '../../.env') });
import express from 'express';
import cors from 'cors';
import { createServer } from 'http';
import { initSocket } from './socket.js';
import { initDb } from './db.js';
import { runMigrations } from './migrate.js';
import { seedAdmin } from './seed.js';
import authRoutes from './routes/auth.js';
import configRoutes from './routes/config.js';
import teamsRoutes from './routes/teams.js';
import judgesRoutes from './routes/judges.js';
import scoresRoutes from './routes/scores.js';
import chatRoutes from './routes/chat.js';
import emailRoutes from './routes/email.js';
import uploadRoutes from './routes/upload.js';
import todoRoutes from './routes/todo.js';
import inviteRoutes from './routes/invite.js';
import checklistRoutes from './routes/checklist.js';
const app = express();
const server = createServer(app);
const frontendPort = process.env.PORT || 3000;
app.use(cors({ origin: [`http://localhost:${frontendPort}`, 'http://localhost:5173'], credentials: true }));
app.use(express.json());
initSocket(server);
app.use('/api/auth', authRoutes);
app.use('/api/config', configRoutes);
app.use('/api/teams', teamsRoutes);
app.use('/api/judges', judgesRoutes);
app.use('/api/scores', scoresRoutes);
app.use('/api/chat', chatRoutes);
app.use('/api/admin', emailRoutes);
app.use('/api/upload', uploadRoutes);
app.use('/api/admin/todo', todoRoutes);
app.use('/api/invite', inviteRoutes);
app.use('/api/teams', checklistRoutes);
app.get('/api/health', (_req, res) => res.json({ ok: true }));
async function start() {
    await initDb();
    runMigrations();
    seedAdmin();
    const PORT = process.env.BACKEND_PORT || 3001;
    server.listen(PORT, () => {
        console.log(`Server running on http://localhost:${PORT}`);
    });
}
start().catch((err) => {
    console.error('Failed to start server:', err);
    process.exit(1);
});
